INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(53511, 'Psalms 73:3', 'Psalms', 73, 3, 'ما ځکه وکړه بخیلي د کبرجنو سره کله چې ما د بدکارانو بریا ولیدله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_3.mp3', '', 1761754199, 1761754199),
(53512, 'Psalms 73:4', 'Psalms', 73, 4, 'هغوی هېڅکله درد لیدلی نه دی دي روغ رمټ او ځواکمن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_4.mp3', '', 1761754199, 1761754199),
(53513, 'Psalms 73:5', 'Psalms', 73, 5, 'د نورو خلکو په شان دوی هېڅ په کړاو کې نه دي د نورو خلکو په شان نه ځوریږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_5.mp3', '', 1761754199, 1761754199),
(53514, 'Psalms 73:6', 'Psalms', 73, 6, 'په غاړه کړی دی دوی کبر د غاړه کۍ په شان او تاوتریخوالی د چپنې په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_6.mp3', '', 1761754199, 1761754199),
(53515, 'Psalms 73:7', 'Psalms', 73, 7, 'له چاغۍ نه یې سترګې رډې راوتلې ښکاري هم یې ذهنونه دي د بدو خیالاتو نه ډک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_7.mp3', '', 1761754199, 1761754199),
(53516, 'Psalms 73:8', 'Psalms', 73, 8, 'په نورو خلکو پورې خاندي هغوی او بدې خبرې کوي په خپل غرور سره دوی د تېري ګواښونه کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_8.mp3', '', 1761754199, 1761754199),
(53517, 'Psalms 73:9', 'Psalms', 73, 9, 'هغوی دي خولې راخلاصې کړې د اسمان په ضد په خپله ژبه یې دنیا وخوړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_9.mp3', '', 1761754199, 1761754199),
(53518, 'Psalms 73:10', 'Psalms', 73, 10, 'حتی تر دې چې د خدای قوم هم پیروي کړي د دوی او څه چې وایي پرې باور هغوی په شوق کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_10.mp3', '', 1761754199, 1761754199),
(53519, 'Psalms 73:11', 'Psalms', 73, 11, 'بدکاران وایي: «خدای به څنګه پوه شي؟ خدای تعالی به په دې پوه شي چې څه کیږي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_11.mp3', '', 1761754199, 1761754199),
(53520, 'Psalms 73:12', 'Psalms', 73, 12, 'وګورئ دغه بدکاره خلک هغوی ارام دي همېش او ورځ په ورځ د دوی دولت زیاتیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_12.mp3', '', 1761754199, 1761754199),
(53521, 'Psalms 73:13', 'Psalms', 73, 13, 'ایا بېځایه مې خپل زړه پاک کړی؟ لاسونه لېرې مې ساتلي له ګناه ځینې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_13.mp3', '', 1761754199, 1761754199),
(53522, 'Psalms 73:14', 'Psalms', 73, 14, 'زه ټوله ورځ کړول کېږم او هر سهار راکول کیږي سزا راته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_14.mp3', '', 1761754199, 1761754199),
(53523, 'Psalms 73:15', 'Psalms', 73, 15, 'داسې خبرې که مې کړې وای نورو ته نو زه به خاین وای ستا ولس ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_15.mp3', '', 1761754199, 1761754199),
(53524, 'Psalms 73:16', 'Psalms', 73, 16, 'ما کوښښ کاوه چې پوه شم په دې ستونزه خو زما دپاره دا وه ډېره سخته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_16.mp3', '', 1761754199, 1761754199),
(53525, 'Psalms 73:17', 'Psalms', 73, 17, 'ترڅو زه لاړمه ای خدایه ستا سپېڅلي کور ته نو بیا زه پوه شومه چې څه به وي قسمت د بدکارانو خلکو:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_17.mp3', '', 1761754199, 1761754199),
(53526, 'Psalms 73:18', 'Psalms', 73, 18, 'بې له شکه تا دي درولي هغوی په ښویېدونکو ځایو ترڅو راولویږي نابود شي هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_18.mp3', '', 1761754199, 1761754199),
(53527, 'Psalms 73:19', 'Psalms', 73, 19, 'دوی ناڅاپه تباه کیږي ډک دی له وېرې او وحشته د هغوی انجام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_19.mp3', '', 1761754199, 1761754199),
(53528, 'Psalms 73:20', 'Psalms', 73, 20, 'دي هغوی د هغه خوب په شان کوم چې هېریږي د سهار په وخت کې چې ته راپاڅې ای څښتنه کله نو ته به هېر کړې هرڅه د دوی په هکله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_20.mp3', '', 1761754199, 1761754199),
(53529, 'Psalms 73:21', 'Psalms', 73, 21, 'کله چې زړه زما خفه ؤ او زما روح زخمي ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_21.mp3', '', 1761754199, 1761754199),
(53530, 'Psalms 73:22', 'Psalms', 73, 22, 'او چې زه ومه بې‌عقل او جاهل ښکاره کېدم به تاته زه د یو حیوان په څېر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_22.mp3', '', 1761754199, 1761754199),
(53531, 'Psalms 73:23', 'Psalms', 73, 23, 'بیاهم تل تاته نژدې یم تا مې نیولی ښي لاس', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_23.mp3', '', 1761754199, 1761754199),
(53532, 'Psalms 73:24', 'Psalms', 73, 24, 'ته لارښوونه مې کوې په مشورو خپلو او رسوې مې ته اخر خپل پر‌جلال حضور ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_24.mp3', '', 1761754199, 1761754199),
(53533, 'Psalms 73:25', 'Psalms', 73, 25, 'په اسمان کې زما څوک دی بې له تا نه؟ په ځمکه هم پرته له تا نه بل څه نه غواړمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_25.mp3', '', 1761754199, 1761754199),
(53534, 'Psalms 73:26', 'Psalms', 73, 26, 'که مې زړه او بدن دواړه شي کمزوري خو بیاهم دی خدای زما د زړه قوت او د تل دپاره به هرڅه وي زما دپاره هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_26.mp3', '', 1761754199, 1761754199),
(53535, 'Psalms 73:27', 'Psalms', 73, 27, 'وګوره، چې څوک د ستا نه لېرې شي تباه به شي کړې به یې نابود هغوی چې تاته وفادار نه دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_27.mp3', '', 1761754199, 1761754199),
(53536, 'Psalms 73:28', 'Psalms', 73, 28, 'خو زما دپاره څومره ښه ده چې د خدای سره نژدې واوسم څښتن تعالی ته مې پناه وروړله بیانوم به یې زه ټول کارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms73_verse_28.mp3', '', 1761754199, 1761754199),
(53537, 'Psalms 44:1', 'Psalms', 44, 1, 'زمونږ نیکونو ته تا کړي لوی کارونه دي دا په ډېره پخوانۍ زمانه کې د هغو، خدایه چې په دې هکله اورېدلي دي مونږ په دې هکله یې ویلي مونږ ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_1.mp3', '', 1761754199, 1761754199),
(53538, 'Psalms 44:2', 'Psalms', 44, 2, 'وشړل تا نور قومونه په خپل لاس باندې د دوی خاوره کې دې خپل قوم مېشته کړ نورو قومونو ته دې څرنګه سزا ورکړله تا په خپل قوم نېکمرغي راوستله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_2.mp3', '', 1761754199, 1761754199),
(53539, 'Psalms 44:3', 'Psalms', 44, 3, 'دا خاوره فتح نه کړه ستا قوم په خپلو تورو هغه یې په خپل قوت ونه ګټله د ستا په زور او په قوت یې هغه وګټله ځکه په دې باندې ډاډه وو هغوی چې ته وې مل ورسره او هم ته وې ډېر د هغوی نه راضي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_3.mp3', '', 1761754199, 1761754199),
(53540, 'Psalms 44:4', 'Psalms', 44, 4, 'ای خدایه! ته زما پاچا یې ته ورکوې بری د یعقوب قوم ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_4.mp3', '', 1761754199, 1761754199),
(53541, 'Psalms 44:5', 'Psalms', 44, 5, 'ورکوو ماتې دښمنانو ته مونږ ستا په مرسته خپل دښمنان پایمالوو مونږه د ستا په قدرت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_5.mp3', '', 1761754199, 1761754199),
(53542, 'Psalms 44:6', 'Psalms', 44, 6, 'خپلې لیندې باندې تکیه نه کوم نه مې په توره چې به خلاص کاندي ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_6.mp3', '', 1761754199, 1761754199),
(53543, 'Psalms 44:7', 'Psalms', 44, 7, 'خو تا له خپلو دښمنانو مونږه خلاص کړلو چا چې له مونږه کړله کرکه دوی دې وشرمول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_7.mp3', '', 1761754199, 1761754199),
(53544, 'Psalms 44:8', 'Psalms', 44, 8, 'مونږه به تل مدام ویل چې کوو فخر په تا تر ابده به کوو مونږ ستا شکرونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_8.mp3', '', 1761754199, 1761754199),
(53545, 'Psalms 44:9', 'Psalms', 44, 9, 'خو اوس دې پرېښودو رسوا دې کړلو زمونږ لښکرو سره نور ته نه ځې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_9.mp3', '', 1761754199, 1761754199),
(53546, 'Psalms 44:10', 'Psalms', 44, 10, 'تا مجبور کړلو چې تېښته له دښمنه وکړو څه چې زمونږه سره وو لوټ کړل هغو چې زمونږه څخه کرکه کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_10.mp3', '', 1761754199, 1761754199),
(53547, 'Psalms 44:11', 'Psalms', 44, 11, 'تا پرېښودلو چې حلال شو د پسونو په شان پردو قومونو کې دې مونږ خواره واره کړلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_11.mp3', '', 1761754199, 1761754199),
(53548, 'Psalms 44:12', 'Psalms', 44, 12, 'په کمه بیه دې خپل قوم خرڅ کړ او دې خرڅلاو درته فایده ونه کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_12.mp3', '', 1761754199, 1761754199),
(53549, 'Psalms 44:13', 'Psalms', 44, 13, 'ګاونډي ملکونه ګوري تا زمونږ سره څه وکړل دوی په مونږ وهي ملنډې او خندا راپورې کاندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_13.mp3', '', 1761754199, 1761754199),
(53550, 'Psalms 44:14', 'Psalms', 44, 14, 'په قومونو کې دې مونږه مسخره کړو له تحقیره خوځوي راته سرونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_14.mp3', '', 1761754199, 1761754199),
(53551, 'Psalms 44:15', 'Psalms', 44, 15, 'مدام رسوا یمه زه په شرمو پټ یمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_15.mp3', '', 1761754199, 1761754199),
(53552, 'Psalms 44:16', 'Psalms', 44, 16, 'اورو مونږ د دښمنانو پېغورونه دښمنان او غچ اخیستونکي وینو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_16.mp3', '', 1761754199, 1761754199),
(53553, 'Psalms 44:17', 'Psalms', 44, 17, 'دا هرڅه وشول په مونږ خو ته مو هېر نه کړلې تا چې زمونږ سره کوم لوظ کړی ؤ مونږه مات کړی نه دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_17.mp3', '', 1761754199, 1761754199),
(53554, 'Psalms 44:18', 'Psalms', 44, 18, 'بې‌وفا نه یو تاته د ستا له لارې ګرځېدلي نه یو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_18.mp3', '', 1761754199, 1761754199),
(53555, 'Psalms 44:19', 'Psalms', 44, 19, 'خو تا مونږ پرېښودو بې‌وسه د وحشي ځناورانو منځ کې تورو تیارو کې دې مونږ پرېښودلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_19.mp3', '', 1761754199, 1761754199),
(53556, 'Psalms 44:20', 'Psalms', 44, 20, 'که مونږ خپل خدای ته وای بس کړی عبادت کول او پردي خدای ته مو دعا کړې وای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_20.mp3', '', 1761754199, 1761754199),
(53557, 'Psalms 44:21', 'Psalms', 44, 21, 'ته په رښتیا به پوهېدلی وای پرې ځکه خبر یې په رازونو د زړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_21.mp3', '', 1761754199, 1761754199),
(53558, 'Psalms 44:22', 'Psalms', 44, 22, 'مونږه له مرګه سره مخ یو هر وخت ستا په خاطر مونږه ګڼي هغو پسونو په شان وي چې حلالې دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_22.mp3', '', 1761754199, 1761754199),
(53559, 'Psalms 44:23', 'Psalms', 44, 23, 'شه رابېداره ای څښتنه! ته ویده ولې یې؟ ته رابېدار شه! تر ابده مونږه مه ردوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_23.mp3', '', 1761754199, 1761754199),
(53560, 'Psalms 44:24', 'Psalms', 44, 24, 'ولې پټوې مخ دې زمونږ ځینې؟ ولې هېروې تکلیفونه او مصیبتونه زمونږ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_24.mp3', '', 1761754199, 1761754199),
(53561, 'Psalms 44:25', 'Psalms', 44, 25, 'مونږ ټوک ټوک شوي رالوېدلي یو په ځمکه باندې مونږ مغلوب شوي یو پراته خاورو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_25.mp3', '', 1761754199, 1761754199),
(53562, 'Psalms 44:26', 'Psalms', 44, 26, 'پورته شه، زمونږ کومک ته راشه ته! مونږ ته نجات راکړه په وجه د تلپاتې مینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms44_verse_26.mp3', '', 1761754199, 1761754199),
(53563, 'Proverbs 12:1', 'Proverbs', 12, 1, 'څوک چې نصیحت مني نو د علم سره مینه لري خو څوک چې له اصلاح نه کرکه کوي بې‌عقله دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_1.mp3', '', 1761754199, 1761754199),
(53564, 'Proverbs 12:2', 'Proverbs', 12, 2, 'ښه انسان د څښتن رضا او خوشحالي حاصلوي خو هغه انسان ته سزا ورکوي چې بدې نقشې جوړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_2.mp3', '', 1761754199, 1761754199),
(53565, 'Proverbs 12:3', 'Proverbs', 12, 3, 'هېڅوک د بدۍ له امله ټینګ نه پاتې کیږي خو د نېکانو ریښه هېڅکله له بېخه نه ویستل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_3.mp3', '', 1761754199, 1761754199),
(53566, 'Proverbs 12:4', 'Proverbs', 12, 4, 'یوه مېړنۍ او پتمنه ښځه د خپل مېړه د سر تاج ده خو هغه ښځه چې د خپل مېړه د شرم سبب ګرځي د هډوکو د سرطان په شان ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_4.mp3', '', 1761754199, 1761754199),
(53567, 'Proverbs 12:5', 'Proverbs', 12, 5, 'د نېکانو ارادې په انصاف سره جوړیږي خو د بدکارانو بدې مشورې انسان غولوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_5.mp3', '', 1761754199, 1761754199),
(53568, 'Proverbs 12:6', 'Proverbs', 12, 6, 'د بدکارانو ژبه وینو تویولو ته تل په کمین کې ده خو د صادقانو ژبه د خلکو ژوند ژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_6.mp3', '', 1761754199, 1761754199),
(53569, 'Proverbs 12:7', 'Proverbs', 12, 7, 'بدکاران مړه کیږي او له منځه ځي خو د نېکانو د کور بنیاد به ټینګ ولاړ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_7.mp3', '', 1761754199, 1761754199),
(53570, 'Proverbs 12:8', 'Proverbs', 12, 8, 'د انسان ستاینه د هغه د هوښیارۍ له مخې کیږي خو د غلط فکر خاوند ته په سپکه سترګه کتل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_8.mp3', '', 1761754199, 1761754199),
(53571, 'Proverbs 12:9', 'Proverbs', 12, 9, 'ښه ده چې انسان عاجز وي او نوکر ولري له هغه چا نه چې ځان لوړ ګڼي او ډوډۍ نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_9.mp3', '', 1761754199, 1761754199),
(53572, 'Proverbs 12:10', 'Proverbs', 12, 10, 'نېک انسان په خپلو حیواناتو باندې هم پام کوي خو د بدکارانو رحم هم له ظلم نه ډک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_10.mp3', '', 1761754199, 1761754199),
(53573, 'Proverbs 12:11', 'Proverbs', 12, 11, 'څوک چې په خپله ځمکه کې کار کوي په ګېډه به موړ شي خو څوک چې د ورځې خوبونه کوي نو ناپوهه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_11.mp3', '', 1761754199, 1761754199),
(53574, 'Proverbs 12:12', 'Proverbs', 12, 12, 'بدکاران له شر اچوونکو نه د لوټ شوي مال تمه کوي خو د نېکانو ریښې تل تازه او حاصل ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_12.mp3', '', 1761754199, 1761754199),
(53575, 'Proverbs 12:13', 'Proverbs', 12, 13, 'بدکاره سړی د خپلو بدو خبرو په دام کې نیول کیږي خو نېک انسان له سختۍ نه ژغورل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_13.mp3', '', 1761754199, 1761754199),
(53576, 'Proverbs 12:14', 'Proverbs', 12, 14, 'انسان د خپلې خولې په هوښیارو خبرو مړیږي او د خپلو لاسونو د کار ثمره ورکول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_14.mp3', '', 1761754199, 1761754199),
(53577, 'Proverbs 12:15', 'Proverbs', 12, 15, 'جاهل سړي ته خپلې لارې چارې سمې ښکاري خو د حکمت خاوند د نورو لارښوونې ته غوږ نیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_15.mp3', '', 1761754199, 1761754199),
(53578, 'Proverbs 12:16', 'Proverbs', 12, 16, 'جاهل سړی خپل قهر زر ښکاره کوي خو ځیرک انسان په خپله بې‌عزتۍ پرده اچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_16.mp3', '', 1761754199, 1761754199),
(53579, 'Proverbs 12:17', 'Proverbs', 12, 17, 'رښتینی انسان په صداقت شهادت ورکوي خو دروغجن شاهد د ټګۍ خبرې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_17.mp3', '', 1761754199, 1761754199),
(53580, 'Proverbs 12:18', 'Proverbs', 12, 18, 'د بې‌پروایۍ خبرې د تورې په څېر غوڅول کوي خو د حکمت د خاوندانو ژبه زخمونو ته شفا ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_18.mp3', '', 1761754199, 1761754199),
(53581, 'Proverbs 12:19', 'Proverbs', 12, 19, 'رښتینې خبرې تل ټینګې پاتې کیږي خو د دروغو مزل لنډ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_19.mp3', '', 1761754199, 1761754199),
(53582, 'Proverbs 12:20', 'Proverbs', 12, 20, 'څوک چې بدې نقشې جوړوي په زړونو کې یې ټګي وي خو د سولې او سلامتۍ غوښتونکي به خوشحاله وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_20.mp3', '', 1761754199, 1761754199),
(53583, 'Proverbs 12:21', 'Proverbs', 12, 21, 'نېک انسان ته هېڅکله زیان نه رسیږي خو بدکاران به تل له مصیبت سره مخامخ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_21.mp3', '', 1761754199, 1761754199),
(53584, 'Proverbs 12:22', 'Proverbs', 12, 22, 'څښتن له دروغ ویلو نه کرکه کوي خو له رښتینو خلکو خوشحاله وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_22.mp3', '', 1761754199, 1761754199),
(53585, 'Proverbs 12:23', 'Proverbs', 12, 23, 'ځیرک انسان خپله پوهه پټه ساتي خو کم‌عقل خلک خپل جهالت ښکاره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_23.mp3', '', 1761754199, 1761754199),
(53586, 'Proverbs 12:24', 'Proverbs', 12, 24, 'زحمت انسان لوړ مقام ته رسوي خو لټي د انسان نه غلام جوړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_24.mp3', '', 1761754199, 1761754199),
(53587, 'Proverbs 12:25', 'Proverbs', 12, 25, 'اندېښمن زړه انسان په غم ککړوي خو د زړه ښې خبرې انسان خوشحالوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_25.mp3', '', 1761754199, 1761754199),
(53588, 'Proverbs 12:26', 'Proverbs', 12, 26, 'نېک سړی د خپل ملګري په پېژندلو کې احتیاط کوي خو د بدکارانو کړه وړه هغوی بې‌لارې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_26.mp3', '', 1761754199, 1761754199),
(53589, 'Proverbs 12:27', 'Proverbs', 12, 27, 'لټ انسان حتی خپل ښکار هم نه شي پخولی خو خواري‌کښ انسان خپل حاصلات زیاتوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_27.mp3', '', 1761754199, 1761754199),
(53590, 'Proverbs 12:28', 'Proverbs', 12, 28, 'د صداقت په لاره کې ژوندون دی او په سمه لاره کې هېڅکله مرګ نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs12_verse_28.mp3', '', 1761754199, 1761754199),
(53591, 'Jeremiah 44:1', 'Jeremiah', 44, 1, 'دا پېغام يرمياه ته د يهوداه د خلقو په حقله ورکړے شو څوک چې د مِصر په جنوبى ښارونو کښې لکه مجدال، تحفنحيس، ميمفِس او څوک چې په بره برخو کښې اوسېدل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_1.mp3', '', 1761754199, 1761754199),
(53592, 'Jeremiah 44:2', 'Jeremiah', 44, 2, '”مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، تاسو هغه تباهى په خپله وليده چې کومه ما په يروشلم او د يهوداه په نورو ټولو ښارونو باندې راوستله. او نن دا شاړ او تباه شوى پراتۀ دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_2.mp3', '', 1761754199, 1761754199),
(53593, 'Jeremiah 44:3', 'Jeremiah', 44, 3, 'ځکه کوم بد کارونه چې هغوئ وکړل. هغوئ زما قهر په هغه خوشبو سوزولو او غېرو معبودانو ته په عبادت کولو راوچت کړو چې نۀ خو هغوئ او نۀ تاسو او نۀ د هغوئ پلار نيکۀ پېژندل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_3.mp3', '', 1761754199, 1761754199),
(53594, 'Jeremiah 44:4', 'Jeremiah', 44, 4, 'ما بار بار تاسو ته خپل خِدمتګاران پېغمبران درولېږل، هغوئ تاسو ته مِنت وکړو چې دا حرامکارى مۀ کوئ د کوم نه چې زۀ نفرت کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_4.mp3', '', 1761754199, 1761754199),
(53595, 'Jeremiah 44:5', 'Jeremiah', 44, 5, 'خو هغوئ د نبيانو خبرو ته غوږ ونۀ نيولو او نۀ يې توجو ورکړه، او هغوئ د خپلو هغه بد عملونو نه راونۀ ګرځېدل او نۀ يې غېر معبودانو ته خوشبو سوزول بند کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_5.mp3', '', 1761754199, 1761754199),
(53596, 'Jeremiah 44:6', 'Jeremiah', 44, 6, 'نو په دې وجه ما خپل سخت قهر د يهوداه په ښارونو او د يروشلم په کوڅو لکه د اور په شان نازل کړو، او هغه يې تر نن ورځ پورې تباه او په خرابه بدل کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_6.mp3', '', 1761754199, 1761754199),
(53597, 'Jeremiah 44:7', 'Jeremiah', 44, 7, 'نو اوس مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې زۀ تاسو نه تپوس کوم چې، تاسو ولې خپل ځانونه تباه کوئ؟ په تاسو کښې به نۀ نارينه، نۀ زنانه، نۀ ماشومان او نۀ تې خوړونکى هيڅوک هم ژوندى پاتې نۀ شى څوک چې دلته د يهوداه نه راغلى يئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_7.mp3', '', 1761754199, 1761754199),
(53598, 'Jeremiah 44:8', 'Jeremiah', 44, 8, 'تاسو په مِصر کښې نورو معبودانو او بُتانو ته د خوشبويۍ نذرانې پېش کولو سره ما ولې غصه کوئ؟ تاسو به په دې کار کولو سره صرف خپل ځان تباه کړئ او د دُنيا د نورو خلقو د لعنت، خندا او مسخرو به وګرځوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_8.mp3', '', 1761754199, 1761754199),
(53599, 'Jeremiah 44:9', 'Jeremiah', 44, 9, 'ولې تاسو د خپل پلار نيکۀ ګناهونه، د يهوداه د بادشاهانو او د مَلِکو ګناهونه، او هغه ګناهونه چې تاسو او ستاسو ښځو په يهوداه او يروشلم کښې کړى دى هېر کړل؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_9.mp3', '', 1761754199, 1761754199),
(53600, 'Jeremiah 44:10', 'Jeremiah', 44, 10, 'خو تر ننه پورې نۀ تاسو په خپل ځان کښې خاکسارى راوستې ده او نۀ مو په خپلو بدو کارونو پښېمانى ښکاره کړې ده. په تاسو کښې هيچا، نۀ زما د شريعت په مطابق او نۀ زما د اصُولو په مطابق ژوند کړے دے کوم چې ما ستاسو نه وړاندې ستاسو پلار نيکۀ ته ورکړى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_10.mp3', '', 1761754199, 1761754199),
(53601, 'Jeremiah 44:11', 'Jeremiah', 44, 11, 'نو په دې وجه، مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، ما په خپله دا کلکه اراده وکړه چې ټوله يهوداه تباه او هلاکه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_11.mp3', '', 1761754199, 1761754199),
(53602, 'Jeremiah 44:12', 'Jeremiah', 44, 12, 'زۀ به د يهوداه هغه ژوندى پاتې شوى خلق راواخلم هغه څوک چا چې په مِصر کښې په پناه اخستو او اوسېدو زور راوړے وو. زۀ به هغوئ تباه کړم. هغوئ ټول لوئ او واړۀ به په مِصر کښې په جنګ، قحط او وبا باندې مړۀ او تباه کړم. او هغوئ به نورو خلقو ته د تهمت، وحشت، لعنت او حقارت مثال وګرځيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_12.mp3', '', 1761754199, 1761754199),
(53603, 'Jeremiah 44:13', 'Jeremiah', 44, 13, 'زۀ به هغوئ ته په مِصر کښې سزا ورکړم لکه څنګه چې مې ورته په يروشلم کښې په جنګ، قحط او وبا سزا ورکړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_13.mp3', '', 1761754199, 1761754199),
(53604, 'Jeremiah 44:14', 'Jeremiah', 44, 14, 'د يهوداه څومره خلق چې دلته مِصر ته پناه اخستو دپاره راغلى دى هغه ټول به دلته هلاک شى. څوک به هم يهوداه ته واپس لاړ نۀ شى. تر دې چې هغوئ به د دوباره هلته د تلو او آبادېدو ډېر خواهش هم کوى. خو په هغوئ کښې به صرف يو څو کسان واپس شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_14.mp3', '', 1761754199, 1761754199),
(53605, 'Jeremiah 44:15', 'Jeremiah', 44, 15, 'د سړو او ښځو يوه لويه ډله چې په هغوئ کښې ځينې کسان په دې موضوع خبر وُو چې د هغوئ ښځو بُتانو ته خوشبويۍ سوزولې او ورسره هغوئ هم څوک چې په شمالى او جنوبى مِصر کښې اوسېدل يرمياه ته يې ووئيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_15.mp3', '', 1761754199, 1761754199),
(53606, 'Jeremiah 44:16', 'Jeremiah', 44, 16, '”کومه خبره چې تا مونږ ته د مالِک خُدائ په نوم وکړه هغې ته به مونږ غوږ نۀ نيسو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_16.mp3', '', 1761754199, 1761754199),
(53607, 'Jeremiah 44:17', 'Jeremiah', 44, 17, 'مونږ به ضرور په خپلو هغه ټولو خبرو عمل کوُو د کومې خبرې چې مونږه منښته کړې ده، مونږ به آسمانې مَلِکې ته خوشبو سوزوُو او هغې ته به د انګورو د شيرې نذرانې پېش کوُو. مونږ به هغه کارونه کوُو لکه څنګه چې به زمونږ پلار نيکۀ، بادشاهانو، سرکارى کسانو د يهوداه په ښارونو او د يروشلم په کوڅو کښې کول. مونږ سره په هغه وخت کښې خوراک ډېر تېر وو او زندګى مو ښۀ وه او مونږ ته هيڅ قسمه تکليف او مصيبت نۀ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_17.mp3', '', 1761754199, 1761754199),
(53608, 'Jeremiah 44:18', 'Jeremiah', 44, 18, 'خو چې د کوم وخت نه مونږ آسمانې مَلِکې ته د خوشبو سوزول او د څښلو نذرانې پېش کولو رسم بند کړے دے نو مونږ سره هيڅ هم نۀ وُو او په جنګ او قحط باندې مړۀ کېدلوُ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_18.mp3', '', 1761754199, 1761754199),
(53609, 'Jeremiah 44:19', 'Jeremiah', 44, 19, 'نو ښځو خپله خبره جارى وساتله او وې وئيل چې، ”ولې ستاسو دا خيال دے چې ګنې زمونږ خاوندانو ته دا پته نشته چې مونږ آسمانې مَلِکې ته خوشبوئى وسوزوله، د څښلو نذرانه او هغه روټۍ چې پرې مو د هغې شکل جوړ کړے وو پېش کړه؟ نه، بلکل داسې نۀ ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_19.mp3', '', 1761754199, 1761754199),
(53610, 'Jeremiah 44:20', 'Jeremiah', 44, 20, 'نو بيا يرمياه هغه ټولو سړو او ښځو ته وفرمائيل چا چې يو شان جواب ورکړے وو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_20.mp3', '', 1761754199, 1761754199);